"""Render measured report tables and explicit research conclusions from artifacts."""
import argparse,json,pathlib,re
import numpy as np

def clean(text):
    # Keep code, paths, scientific notation and standard model/percentile labels.
    pattern=r"(```[\s\S]*?```|`[^`]*`|https?://[^\s)]+|\b(?:L[234](?:\.5)?|P(?:50|95|99)s?|HM3D|MP3D|100k|500k|1M)\b|\d+(?:\.\d+)?e[+-]?\d+)"
    chunks=re.split(pattern,text)
    for i in range(0,len(chunks),2):
        v=chunks[i]
        v=re.sub(r'([A-Za-z])(?=\d)',r'\1 ',v)
        v=re.sub(r'(\d)(?=[A-Za-z])',r'\1 ',v)
        v=re.sub(r'(?<=[A-Za-z%\]])([,;])(?=\S)',r'\1 ',v)
        for a,b in [('sourcequeries','source queries'),('holdoutroots','holdout roots'),('nearzero','near zero'),('excludingzero','excluding zero'),('is`','is `'),('memoryCV','memory CV'),('P95 s','P95 values')]:v=v.replace(a,b)
        chunks[i]=v
    return ''.join(chunks)

def run(directory,docs):
    root=pathlib.Path(directory);docs=pathlib.Path(docs);s=json.loads((root/'release_metrics.json').read_text());lat=json.loads((root/'latency_release.json').read_text());a=json.loads((root/'failure_diagnostics.json').read_text())
